//! The text lists of plugins: `Plugins.txt`, which says which plugins are
//! on, and `loadorder.txt`, which the mod manager keeps with every plugin in
//! its order (ADR 0089).
//!
//! Both are lines of file names, comments starting with `#`. In
//! `Plugins.txt` of Skyrim Special Edition and the games like it, a `*`
//! before the name means the plugin is on. Who wrote a list is told by its
//! first comment: the game writes one of its own ("This file is used by
//! Skyrim to keep track of your downloaded content."), Vortex another
//! ("Automatically generated by Vortex"). Only reads.

use std::path::Path;

use mallet_core::facts::plugin_list::{MissingMaster, OffReason, SwitchedOffByGame};
use mallet_core::{GamePath, ModSource, SwitchedOffPlugin};
use mallet_formats_bethesda::plugin;

use crate::game::Game;

/// Who wrote a list of plugins, as its comments tell.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Writer {
    /// The game, when it started.
    Game,
    /// Vortex.
    Vortex,
    /// Someone else, or the list does not say.
    Other,
}

/// A list of plugins as read.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PluginList {
    /// Who wrote it.
    pub writer: Writer,
    /// The plugins in the order listed, each with whether it is on. In a
    /// list without `*`, every plugin listed is on.
    pub entries: Vec<(String, bool)>,
}

impl PluginList {
    /// Reads the text of a list. `asterisks` says whether a `*` marks the
    /// plugins that are on; otherwise every plugin listed is.
    pub fn parse(text: &str, asterisks: bool) -> Self {
        let mut writer = Writer::Other;
        let mut entries = Vec::new();
        for line in text.lines() {
            let line = line.trim_start_matches('\u{FEFF}').trim();
            if let Some(comment) = line.strip_prefix('#') {
                if writer == Writer::Other {
                    writer = writer_of(comment);
                }
                continue;
            }
            if line.is_empty() {
                continue;
            }
            let (name, on) = match line.strip_prefix('*') {
                Some(name) => (name.trim(), true),
                None => (line, !asterisks),
            };
            if !name.is_empty() {
                entries.push((name.to_owned(), on));
            }
        }
        Self { writer, entries }
    }

    /// The plugins that are on, in order.
    pub fn active(&self) -> impl Iterator<Item = &str> {
        self.entries
            .iter()
            .filter(|(_, on)| *on)
            .map(|(name, _)| name.as_str())
    }

    /// The plugins that are off and listed before the first that is on.
    /// The game puts the plugins it switched off itself there.
    pub fn off_at_the_top(&self) -> impl Iterator<Item = &str> {
        self.entries
            .iter()
            .take_while(|(_, on)| !*on)
            .map(|(name, _)| name.as_str())
    }
}

/// The most full plugins the game loads; the rest of the 256 slots are the
/// game's own and the light plugins'.
const MOST_FULL: usize = 254;

/// The most light plugins the game loads.
const MOST_LIGHT: usize = 4096;

/// What the game's own list says, if the game itself last wrote it
/// (ADR 0089): the plugins it switched off that `manager_order`, the mod
/// manager's own load order, has, each with why. `active` are the plugins
/// the game loads, `mods` tells which mod brings a file, `switched_off`
/// are the plugins of mods the manager keeps off. Empty where the game did
/// not write the list, or switched nothing off. Only reads.
pub fn game_rewrite(
    game: Game,
    data_dir: &Path,
    list: &PluginList,
    manager_order: Option<&PluginList>,
    active: &[String],
    mods: &dyn ModSource,
    switched_off: &[SwitchedOffPlugin],
) -> Vec<SwitchedOffByGame> {
    if list.writer != Writer::Game || !uses_asterisks(game) {
        return Vec::new();
    }
    let is_active = |name: &str| active.iter().any(|known| known.eq_ignore_ascii_case(name));
    let on_top: Vec<&str> = list.off_at_the_top().collect();
    let data = GamePath::new("data");
    let mut found: Vec<SwitchedOffByGame> = Vec::new();
    for (name, on) in &list.entries {
        if *on || is_active(name) || game.is_official(name) {
            continue;
        }
        let reason = reason_of(data_dir, name, &is_active, switched_off);
        // The game moves what it switched off to the top; a plugin off
        // elsewhere was switched off by someone, unless the game could not
        // load it anyway.
        let refused = !matches!(reason, OffReason::Unknown | OffReason::TooMany);
        if !on_top.contains(&name.as_str()) && !refused {
            continue;
        }
        let mod_ref = mods.provider_of(&data.join(name));
        found.push(SwitchedOffByGame {
            plugin: name.clone(),
            mod_ref,
            reason,
        });
    }
    // A plugin the mod manager does not list it did not have on.
    if let Some(order) = manager_order {
        found.retain(|plugin| {
            order
                .entries
                .iter()
                .any(|(name, _)| name.eq_ignore_ascii_case(&plugin.plugin))
        });
        found.sort_by_key(|plugin| {
            order
                .entries
                .iter()
                .position(|(name, _)| name.eq_ignore_ascii_case(&plugin.plugin))
        });
    }
    let unknown = found
        .iter()
        .any(|plugin| plugin.reason == OffReason::Unknown);
    if unknown && too_many(data_dir, active) {
        for plugin in &mut found {
            if plugin.reason == OffReason::Unknown {
                plugin.reason = OffReason::TooMany;
            }
        }
    }
    found
}

/// Whether the game marks the plugins that are on with `*`.
fn uses_asterisks(game: Game) -> bool {
    matches!(
        game,
        Game::SkyrimSe | Game::SkyrimVr | Game::EnderalSe | Game::Fallout4 | Game::Fallout4Vr
    )
}

/// Why the game cannot load the plugin `name` from `data_dir`.
fn reason_of(
    data_dir: &Path,
    name: &str,
    is_active: &dyn Fn(&str) -> bool,
    switched_off: &[SwitchedOffPlugin],
) -> OffReason {
    let path = data_dir.join(name);
    let Ok(file) = std::fs::File::open(&path) else {
        return OffReason::NotFound;
    };
    let Ok(read) = plugin::read(&mut std::io::BufReader::new(file), &[]) else {
        return OffReason::Unreadable;
    };
    let missing: Vec<MissingMaster> = read
        .header
        .masters
        .iter()
        .filter(|master| !is_active(master))
        .map(|master| MissingMaster {
            plugin: master.clone(),
            present: data_dir.join(master).is_file(),
            switched_off_mod: switched_off
                .iter()
                .find(|plugin| plugin.plugin.eq_ignore_ascii_case(master))
                .map(|plugin| plugin.mod_ref.clone()),
        })
        .collect();
    if missing.is_empty() {
        OffReason::Unknown
    } else {
        OffReason::MissingMasters(missing)
    }
}

/// Whether more full or more light plugins are on than the game loads.
fn too_many(data_dir: &Path, active: &[String]) -> bool {
    if active.len() <= MOST_FULL {
        return false;
    }
    let mut light = 0usize;
    for name in active {
        let is_light = Path::new(name)
            .extension()
            .is_some_and(|ending| ending.eq_ignore_ascii_case("esl"))
            || std::fs::File::open(data_dir.join(name))
                .ok()
                .and_then(|file| plugin::read(&mut std::io::BufReader::new(file), &[]).ok())
                .is_some_and(|read| read.header.is_light);
        if is_light {
            light += 1;
        }
    }
    active.len().saturating_sub(light) > MOST_FULL || light > MOST_LIGHT
}

/// Who wrote a list, by one of its comments.
fn writer_of(comment: &str) -> Writer {
    let lower = comment.to_lowercase();
    if lower.contains("generated by vortex") {
        Writer::Vortex
    } else if lower.contains("this file is used by") && lower.contains("keep track of") {
        Writer::Game
    } else {
        Writer::Other
    }
}

/// The text of a list's bytes: UTF-8 where it is, otherwise Windows-1252,
/// which the games and older tools write.
pub fn text_of(bytes: &[u8]) -> String {
    match std::str::from_utf8(bytes) {
        Ok(text) => text.to_owned(),
        Err(_) => bytes.iter().map(|byte| windows_1252(*byte)).collect(),
    }
}

/// One byte of Windows-1252 as a character. The bytes 0x80 to 0x9F that
/// the code page leaves unused stand for themselves.
fn windows_1252(byte: u8) -> char {
    const HIGH: [char; 32] = [
        '€', '\u{81}', '‚', 'ƒ', '„', '…', '†', '‡', 'ˆ', '‰', 'Š', '‹', 'Œ', '\u{8D}', 'Ž',
        '\u{8F}', '\u{90}', '‘', '’', '“', '”', '•', '–', '—', '˜', '™', 'š', '›', 'œ', '\u{9D}',
        'ž', 'Ÿ',
    ];
    match byte {
        0x80..=0x9F => HIGH
            .get(usize::from(byte - 0x80))
            .copied()
            .unwrap_or(char::REPLACEMENT_CHARACTER),
        _ => char::from(byte),
    }
}

#[cfg(test)]
mod tests {
    use proptest::prelude::*;

    use super::*;

    #[test]
    fn the_games_own_list_puts_what_it_switched_off_first() {
        let text = "# This file is used by Skyrim to keep track of your downloaded content.\n\
                    # Please do not modify this file.\n\
                    Patch A.esp\n\
                    Patch B.esp\n\
                    *Town.esp\n\
                    Old.esp\n\
                    *City.esm\n";
        let list = PluginList::parse(text, true);
        assert_eq!(list.writer, Writer::Game);
        assert_eq!(
            list.active().collect::<Vec<_>>(),
            vec!["Town.esp", "City.esm"]
        );
        assert_eq!(
            list.off_at_the_top().collect::<Vec<_>>(),
            vec!["Patch A.esp", "Patch B.esp"]
        );
    }

    #[test]
    fn vortex_writes_its_own_header_and_a_list_without_stars_is_all_on() {
        let list = PluginList::parse(
            "# Automatically generated by Vortex\r\n*A.esp\r\nB.esp\r\n",
            true,
        );
        assert_eq!(list.writer, Writer::Vortex);
        assert_eq!(list.active().collect::<Vec<_>>(), vec!["A.esp"]);
        let order = PluginList::parse(
            "# Automatically generated by Vortex\nSkyrim.esm\nB.esp\n",
            false,
        );
        assert_eq!(order.active().count(), 2);
        assert_eq!(order.off_at_the_top().count(), 0);
        assert_eq!(PluginList::parse("A.esp\n", true).writer, Writer::Other);
    }

    #[test]
    fn names_outside_utf8_are_read_as_windows_1252() {
        assert_eq!(text_of(b"*Caf\xE9 \x80.esp\n"), "*Café €.esp\n");
        assert_eq!(text_of("*Café.esp".as_bytes()), "*Café.esp");
    }

    #[test]
    fn a_patch_whose_master_is_off_is_found_with_the_mod_that_has_it() {
        let data = tempfile::tempdir().unwrap();
        let write = |name: &str, masters: &[&str]| {
            std::fs::write(
                data.path().join(name),
                mallet_formats_bethesda::fixture::plugin_with_raw_groups(masters, 0, &[]),
            )
            .unwrap();
        };
        write("Skyrim.esm", &[]);
        write("Town.esp", &["Skyrim.esm"]);
        write("Forge Patch.esp", &["Skyrim.esm", "Forge.esp"]);
        write("Mine.esp", &["Skyrim.esm"]);
        std::fs::write(data.path().join("Broken.esp"), b"not a plugin").unwrap();
        let list = PluginList::parse(
            "# This file is used by Skyrim to keep track of your downloaded content.\n\
             Forge Patch.esp\nGone.esp\nBroken.esp\n*Town.esp\nMine.esp\n",
            true,
        );
        let order = PluginList::parse(
            "# Automatically generated by Vortex\n\
             Skyrim.esm\nGone.esp\nTown.esp\nBroken.esp\nForge Patch.esp\nMine.esp\n",
            false,
        );
        let forge = mallet_core::ModRef {
            source: "vortex".to_owned(),
            id: "forge".to_owned(),
            name: "Forge".to_owned(),
        };
        let switched_off = [SwitchedOffPlugin {
            plugin: "Forge.esp".to_owned(),
            mod_ref: forge.clone(),
            loaded: false,
            left_behind: Vec::new(),
        }];
        let active = ["Skyrim.esm".to_owned(), "Town.esp".to_owned()];
        let found = game_rewrite(
            Game::SkyrimSe,
            data.path(),
            &list,
            Some(&order),
            &active,
            &mallet_core::NoModSource,
            &switched_off,
        );
        // In the manager's order; Mine.esp, off further down and
        // loadable, was switched off by someone else.
        assert_eq!(
            found,
            vec![
                SwitchedOffByGame {
                    plugin: "Gone.esp".to_owned(),
                    mod_ref: None,
                    reason: OffReason::NotFound,
                },
                SwitchedOffByGame {
                    plugin: "Broken.esp".to_owned(),
                    mod_ref: None,
                    reason: OffReason::Unreadable,
                },
                SwitchedOffByGame {
                    plugin: "Forge Patch.esp".to_owned(),
                    mod_ref: None,
                    reason: OffReason::MissingMasters(vec![MissingMaster {
                        plugin: "Forge.esp".to_owned(),
                        present: false,
                        switched_off_mod: Some(forge),
                    }]),
                },
            ]
        );
        // A list Vortex wrote is its own: nothing to tell.
        let own = PluginList::parse(
            "# Automatically generated by Vortex\nForge Patch.esp\n",
            true,
        );
        assert_eq!(
            game_rewrite(
                Game::SkyrimSe,
                data.path(),
                &own,
                Some(&order),
                &active,
                &mallet_core::NoModSource,
                &switched_off,
            ),
            Vec::new()
        );
    }

    proptest! {
        #[test]
        fn never_panics(bytes in prop::collection::vec(any::<u8>(), 0..400), asterisks: bool) {
            let list = PluginList::parse(&text_of(&bytes), asterisks);
            let _ = list.active().count();
            let _ = list.off_at_the_top().count();
        }
    }
}
